      "content": "import { expect, test } from 'bun:test';
import { DomainError, type DomainEvent, type UseCaseContext } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { CompleteTask } from '../application/complete-task';
import { Task } from '../domain/task';
import { TaskCompleted } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

async function setup() {
  const task = Task.create('t1', 'Concluir tarefa');
  task.pullEvents();
  const storage = new InMemoryTaskRepository();
  await storage.save(task);
  const calls: string[] = [];
  const savedStatuses: string[] = [];
  const published: DomainEvent[] = [];
  const repository: TaskRepository = {
    async findById(id) {
      calls.push(`load:${id}`);
      return storage.findById(id);
    },
    async save(aggregate) {
      await storage.save(aggregate);
      savedStatuses.push(aggregate.status);
      calls.push(`save:${aggregate.id}`);
    },
  };
  const ctx: UseCaseContext = {
    correlationId: 'correlation-1',
    causationId: 'causation-1',
    async publish(events) {
      calls.push('publish');
      published.push(...events);
    },
  };
  return { task, storage, calls, savedStatuses, published, repository, ctx };
}

test(covers([
  'usecase:complete_task',
  'criterion:0001/persistencia-conclusao',
], 'carrega t1, salva completed e publica TaskCompleted após persistir'), async () => {
  const fixture = await setup();
  const ctx: UseCaseContext = {
    ...fixture.ctx,
    async publish(events) {
      expect(fixture.savedStatuses).toEqual(['completed']);
      expect((await fixture.storage.findById('t1'))?.status).toBe('completed');
      await fixture.ctx.publish(events);
    },
  };

  const output = await new CompleteTask(fixture.repository).execute({ task_id: 't1' }, ctx);

  expect(output).toEqual({ task_id: 't1', status: 'completed' });
  expect(fixture.calls).toEqual(['load:t1', 'save:t1', 'publish']);
  expect(fixture.published).toHaveLength(1);
  expect(fixture.published[0]).toBeInstanceOf(TaskCompleted);
  expect(fixture.published[0]?.payload).toEqual({ taskId: 't1' });
  expect(fixture.published[0]?.correlationId).toBe(ctx.correlationId);
  expect(fixture.published[0]?.causationId).toBe(ctx.causationId);
  expect(fixture.task.pullEvents()).toEqual([]);
});

test(covers([
  'usecase:complete_task',
  'criterion:0001/persistencia-conclusao',
], 'rejeita id inexistente com TASK_NOT_FOUND sem salvar ou publicar'), async () => {
  const fixture = await setup();
  const execution = new CompleteTask(fixture.repository).execute({ task_id: 'missing' }, fixture.ctx);

  await expect(execution).rejects.toBeInstanceOf(DomainError);
  await expect(execution).rejects.toHaveProperty('code', 'TASK_NOT_FOUND');
  expect(fixture.calls).toEqual(['load:missing']);
  expect(fixture.savedStatuses).toEqual([]);
  expect(fixture.published).toEqual([]);
  expect(fixture.task.status).toBe('pending');
});

test(covers([
  'usecase:complete_task',
], 'rejeita segunda conclusão com TASK_ALREADY_COMPLETED sem nova gravação ou publicação'), async () => {
  const fixture = await setup();
  const useCase = new CompleteTask(fixture.repository);
  await useCase.execute({ task_id: 't1' }, fixture.ctx);
  fixture.calls.length = 0;

  const execution = useCase.execute({ task_id: 't1' }, fixture.ctx);

  await expect(execution).rejects.toBeInstanceOf(DomainError);
  await expect(execution).rejects.toHaveProperty('code', 'TASK_ALREADY_COMPLETED');
  expect(fixture.calls).toEqual(['load:t1']);
  expect(fixture.savedStatuses).toEqual(['completed']);
  expect(fixture.published).toHaveLength(1);
  expect(fixture.task.status).toBe('completed');
  expect(fixture.task.pullEvents()).toEqual([]);
});

test(covers([
  'usecase:complete_task',
], 'propaga falha ao salvar e não publica eventos antes da persistência'), async () => {
  const fixture = await setup();
  const failure = new Error('Falha de persistência');
  const repository: TaskRepository = {
    findById: fixture.repository.findById,
    async save() {
      await Promise.resolve();
      throw failure;
    },
  };

  await expect(new CompleteTask(repository).execute({ task_id: 't1' }, fixture.ctx)).rejects.toBe(failure);

  expect(fixture.calls).toEqual(['load:t1']);
  expect(fixture.published).toEqual([]);
  expect(fixture.task.pullEvents()[0]).toBeInstanceOf(TaskCompleted);
});
